{"description":"Measure checker periods across rows","cmd":"cd /tmp && timeout 300 python3 - <<'EOF'
with open('/tmp/img.raw','rb') as f:
    data = f.read()
cols, rows = 2400, 1800
def floorval(x,y):
    p=(y*cols+x)*3
    r=data[p]
    return r
# measure period at each row (average width of runs of constant value among 152/67)
for y in range(900, 1800, 50):
    # find runs
    prev=None; run_start=0; widths=[]
    for x in range(cols):
        v=floorval(x,y)
        if v not in (152,67):
            # skip shadow/red regions for period measurement; treat as gap
            # simpler: collect over full row filtering to floor colors
            pass
        if v!=prev:
            if prev in (152,67) and run_start<cols:
                widths.append(x-run_start)
            run_start=x; prev=v
    if prev in (152,67):
        widths.append(cols-run_start)
    # filter widths that are floor runs (ignore shadow gaps by only collecting alternating)
    # Actually this includes wide gaps due to shadow; let's instead compute transitions count
    transitions=0
    prev=None
    for x in range(10, cols-10):
        v=floorval(x,y)
        if v in (152,67):
            if prev in (152,67) and v!=prev:
                transitions+=1
            prev=v
        else:
            prev=None
    # avg period in pixels = 2400-ish / transitions per (half period)
    avgw = (cols-20)/(max(transitions,1)/2)
    print(y, "transitions=",transitions, "avg run width~", round(avgw,2))
EOF"}

