with open('/tmp/img.raw','rb') as f:
    data = f.read()
cols, rows = 2400, 1800
# Use x range 0..800 (left side, no shadow in most rows), measure period for each y
for y in [905, 910, 930, 970, 1030, 1110, 1230, 1390, 1600, 1799]:
    prev=None; runs=[]
    start=0
    for x in range(0, 800):
        p=(y*cols+x)*3
        r=data[p]
        if r in (152,67):
            v=r
        else:
            v=None
        if v!=prev:
            if prev in (152,67):
                runs.append((prev,x-start,start,x-1))
            start=x; prev=v
    if prev in (152,67):
        runs.append((prev,800-start,start,799))
    # widths of alternating runs: compute median width
    widths=[w for _,w,_,_ in runs if 5<=w]
    if widths:
        med=sorted(widths)[len(widths)//2]
        print(y, "runs:", len(runs), "median width:", med, "min/max:", min(widths), max(widths))
    print("   runs sample:", [(c,w) for c,w,_,_ in runs[:12]])
