{"description":"Test floor/truncation for sky","cmd":"cd /tmp && timeout 300 python3 - <<'EOF'
import math
with open('/tmp/img.raw','rb') as f:
    data=f.read()
cols=2400
def test(roundfn):
    errs=[]
    for y in range(0,899,3):
        for x in range(0,2400,5):
            p=(y*cols+x)*3
            if data[p+2]==255:
                u=x-1200; v=900-y
                d=v/math.sqrt(u*u+v*v+900*900)
                s=1.0-min(1.0, d*math.sqrt(2))
                r=roundfn(146+45*s)
                g=roundfn(190+27*s)
                errs.append(abs(r-data[p])+abs(g-data[p+1]))
    return sum(errs)/len(errs), max(errs)
for name,fn in [("round",round),("floor",math.floor),("int",lambda x:int(x)),("ceil",math.ceil)]:
    mean,mx=test(fn)
    print(name, "mean", mean, "max", mx)
# Check specific: which pixels have R residual -1 with round?
# find where round is 1 too high => actual R = pred-1
cnt=0; samples=[]
for y in range(0,899):
    for x in range(0,2400,3):
        p=(y*cols+x)*3
        if data[p+2]==255:
            u=x-1200; v=900-y
            d=v/math.sqrt(u*u+v*v+900*900)
            s=1.0-min(1.0, d*math.sqrt(2))
            r=round(146+45*s)
            if r-data[p]==1:
                cnt+=1
                if len(samples)<5: samples.append((x,y,146+45*s,r,data[p]))
print("round overguess count:",cnt,"samples:",samples)
